import {CARDS,card,ACTS,fresh,validSave,start,encounter,play,endTurn,reward,upgrade,pressure} from './game.mjs';
const root=document.querySelector('#app');let state=null,modal=null,status='Saved',error='',saving=Promise.resolve();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const sprite=(n=0)=>`<div class="sprite s${n}" role="img" aria-label="${['Job seeker','Résumé scanner','Ghost recruiter','Technical interviewer','Offer committee','Coffee break'][n]}"></div>`;
function cardView(id,index=null,action='play'){const c=card(id);return `<button class="card ${c.type}" ${index!==null?`data-action="${action}:${index}"`:''} ${action==='play'&&index!==null&&c.cost>state.run.energy?'disabled':''}><span class="card-top">${c.type}<span class="cost">${c.cost}</span></span><h3>${c.name}</h3><span class="effect">${c.text}</span><span class="card-bottom">${c.type==='skill'?'TECHNICAL SKILL':c.type==='network'?'PEOPLE POWER':'SELF-PRESERVATION'}</span></button>`}
function side(){const r=state.run;return `<aside><div class="eyebrow">Your application</div><div class="stat"><div class="stat-line"><span>Confidence</span><strong>${r.hp} / ${r.maxHp}</strong></div><div class="meter" role="meter" aria-label="Confidence" aria-valuenow="${Math.max(0,r.hp)}" aria-valuemin="0" aria-valuemax="${r.maxHp}"><span style="width:${Math.max(0,r.hp/r.maxHp*100)}%"></span></div></div><div class="stat"><div class="stat-line"><span>Experience</span><strong>${state.meta.xp} XP</strong></div></div><div class="route">${ACTS.map((a,i)=>`<div class="stage ${Math.floor(r.stage/3)===i?'current':''}"><span class="number">${r.stage>i*3+2?'✓':i+1}</span><span>${a}</span></div>`).join('')}</div><div class="side-footer">${r.deck.length} cards in your deck<br>Attempt #${state.meta.runs}<br><br>Every rejection is character development. Allegedly.</div></aside>`}
function home(){return `<div class="intro"><div><div class="eyebrow">A tech job-hunting roguelite</div><h1>WE’LL BE<br>IN <span style="color:var(--green)">TOUCH.</span></h1><p>Build your deck. Survive the interviews.<br>Try to land a job before you lose your mind.</p>${sprite(0)}<div class="run-facts"><span>9 encounters</span><span>3 interview bosses</span><span>30 cards to discover</span></div></div><div class="start-panel"><div class="eyebrow">Application status: optimistic</div><h2>Your next opportunity awaits.</h2><p>Turn technical skills, unlikely referrals, and healthy boundaries into a winning hand.</p>${btn('Submit application · New run','start','primary')}<div class="stat-line" style="margin-top:24px"><span>Career experience</span><strong>${state.meta.xp} XP</strong></div><div class="stat-line"><span>Offers secured</span><strong>${state.meta.wins}</strong></div><p style="font-size:14px">Resilience ${state.meta.upgrades}/6 · Start with ${60+state.meta.upgrades*5} confidence.</p>${btn(`Build resilience · ${25+state.meta.upgrades*15} XP`,'upgrade','',state.meta.xp<25+state.meta.upgrades*15||state.meta.upgrades>=6)}<div class="bottom-tools">${btn('How to play','help')}${btn('Save & transfer','saves')}</div></div></div>`}
function map(){const r=state.run,boss=r.stage%3===2;return `<div class="title-row"><div><div class="eyebrow">${ACTS[Math.min(2,Math.floor(r.stage/3))]}</div><h2>Choose your next move.</h2></div><span class="pill">Encounter ${r.stage+1} / 9</span></div><div class="map-banner">${sprite(boss?[1,3,4][Math.floor(r.stage/3)]:2)}<div class="banner-text"><div class="eyebrow">${boss?'Mandatory interview':'The hiring pipeline'}</div><h2>${boss?['Beat the résumé filter.','Prove your technical skills.','Close the deal.'][Math.floor(r.stage/3)]:'Another day. Another opportunity.'}</h2><p>${boss?'You’ve made it this far. Your deck does the talking.':'Choose an interview for a card reward, a break to recover, or a mixer to expand your deck.'}</p></div></div><div class="choices">${boss?`<button class="choice" data-action="encounter:fight"><span class="eyebrow">Boss encounter</span><strong>Enter the interview</strong><p>Make enough progress before pressure drains your confidence.</p></button>`:`<button class="choice" data-action="encounter:fight"><span class="eyebrow">Fight · Draft a card</span><strong>Pursue an opportunity</strong><p>Face the hiring chaos. Earn experience and a new card if you advance.</p></button><button class="choice" data-action="encounter:rest"><span class="eyebrow">Rest · +12 confidence</span><strong>Close the laptop</strong><p>Take a real break. No networking. No résumé optimization.</p></button><button class="choice" data-action="encounter:event"><span class="eyebrow">Event · −4 confidence</span><strong>Networking mixer</strong><p>Gain a random networking card. Small talk has a price.</p></button>`}</div>`}
function combat(){const r=state.run,e=r.enemy;return `<div class="title-row"><div><div class="eyebrow">${ACTS[Math.floor(r.stage/3)]} · Round ${r.turn}</div><h2>${e.boss?'The boss interview':'An opportunity appears'}</h2></div><span class="pill">${e.boss?'BOSS':'ENCOUNTER '+(r.stage+1)}</span></div><div class="arena"><div class="actor">${sprite(0)}<div class="actor-name">The hopeful applicant</div><div class="intent" style="color:var(--blue);background:#22313c">${r.block} composure</div><p class="quote">“I’m passionate about paying rent.”</p></div><div class="versus">VS</div><div class="actor">${sprite(e.sprite)}<div class="actor-name">${esc(e.name)}</div><div class="meter enemy-bar" role="meter" aria-label="Interview progress remaining" aria-valuenow="${Math.max(0,e.hp)}" aria-valuemin="0" aria-valuemax="${e.maxHp}"><span style="width:${Math.max(0,e.hp/e.maxHp*100)}%"></span></div><div class="deck-counts">${Math.max(0,e.hp)} / ${e.maxHp} progress remaining</div><div class="intent">Next pressure: ${pressure(r)}</div><p class="quote">${esc(e.quote)}</p></div></div><div class="combat-controls"><div><span class="energy">◆ ${r.energy} / 3 energy</span><div class="deck-counts" style="margin-top:8px">Draw ${r.draw.length} · Discard ${r.discard.length} · Hand ${r.hand.length}</div></div>${btn('End turn','end','primary')}</div><div class="hand" aria-label="Your hand">${r.hand.map((id,i)=>cardView(id,i)).join('')||'<p>Your hand is empty. End your turn to draw again.</p>'}</div>`}
function rewards(){return `<div class="title-row"><div><div class="eyebrow">You’re moving forward</div><h2>A little more employable.</h2></div><span class="pill">CARD REWARD</span></div><p>Choose one card to add to your deck for the rest of this run.</p><div class="hand">${state.run.rewards.map(id=>cardView(id,id,'reward')).join('')}</div>${btn('Keep my deck lean · Skip','reward:skip')}`}
function result(){const won=state.run.phase==='won';return `<div class="result ${won?'':'loss'}"><div class="eyebrow">Application ${won?'successful':'closed'}</div>${sprite(won?4:0)}<h1>${won?'YOU GOT THE OFFER.':'WE WENT IN ANOTHER DIRECTION.'}</h1><p>${won?'It only took a heroic amount of preparation and several improbable referrals.':'Your confidence ran out. Your experience stays with you.'}</p><p>${state.run.earned+(won?30:8)} XP earned · ${state.meta.xp} XP available</p><div class="bottom-tools" style="justify-content:center">${btn('Return to career hub','hub','primary')}${btn('Inspect this deck','deck')}</div></div>`}
function modalView(){if(!modal)return '';let content='';if(modal==='deck'){content=`<p>${state.run.deck.length} cards · Cards are shuffled at each encounter.</p><div class="deck-grid">${state.run.deck.map(id=>cardView(id)).join('')}</div>`}if(modal==='help')content=`<ol class="help-list"><li>Choose a path. Every third encounter is a mandatory boss.</li><li>You draw five cards and receive three energy each turn. Tap a card to play it.</li><li>Progress brings the interview closer to completion. Composure absorbs the enemy’s visible pressure.</li><li>End turn to face pressure and draw a new hand. Composure resets each turn; confidence carries between encounters.</li><li>Every third turn brings 4 extra pressure. Weakening cards reduce pressure for the current turn.</li><li>Draft cards after victories. Rest and healing cards restore confidence.</li><li>Finish or fail a run to earn experience. Spend it on permanent starting-confidence upgrades.</li></ol><p>Keyboard: 1–0 plays a hand card, E ends your turn. Touch and mouse work too.</p>`;if(modal==='saves')content=`<p>Your application file is saved in this browser after every move. Your progress stays on this device until you export it.</p><p>To move to another device, export your save and import it there. Clearing browser data removes your progress; an export lets you recover it.</p><div class="bottom-tools">${btn('Export save','export','primary')}${btn('Import save','import')}${btn('Retry save','retry')}</div><input type="file" id="import-file" accept="application/json" class="hidden"><p>Save status: ${esc(status)}</p>`;return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${modal==='deck'?'Your deck':modal==='help'?'How to survive':'Save & transfer'}</h2>${btn('Close','close')}</div>${content}</section></div>`}
function render(){if(!state)return;const r=state.run;root.innerHTML=`<div class="shell"><header><div><div class="brand">WE’LL BE IN <b>TOUCH.</b></div><div class="tag">THE JOB HUNT IS THE DUNGEON.</div></div><div class="top-actions"><span class="save-label" aria-live="polite">${esc(status)}</span>${r?btn('Deck','deck'):''}${btn('?','help')}${btn('Save','saves')}</div></header>${error?`<div class="notice" role="alert">${esc(error)} ${btn('Retry','retry')}</div>`:''}${r?`<div class="workspace">${side()}<main>${r.phase==='map'?map():r.phase==='combat'?combat():r.phase==='reward'?rewards():result()}<div class="log" aria-live="polite">${r.log.map(l=>`<div>${esc(l)}</div>`).join('')}</div></main></div>`:`<main>${home()}</main>`}</div>${modalView()}`;if(modal){root.querySelector('.modal button')?.focus()} }
async function request(method,body){
 if(method==='GET'){const raw=localStorage.getItem('wbit-progress-v1');return {state:raw?JSON.parse(raw):null}}
 localStorage.setItem('wbit-progress-v1',JSON.stringify(body));return {saved:true};
}
function save(){status='Saving…';const snapshot=structuredClone(state);saving=saving.catch(()=>{}).then(()=>request('PUT',snapshot)).then(()=>{status='Saved';error='';render()}).catch(e=>{status='Save failed';error='Could not save in this browser. Export a backup from Save & transfer. '+e.message;render()});render();return saving}
async function load(){try{const data=await request('GET');state=data.state||fresh();if(!validSave(state))throw Error('This save could not be read. Your stored file has not been changed.');render()}catch(e){root.innerHTML=`<div class="shell"><h1>Application file unavailable.</h1><p>${esc(e.message)}</p>${btn('Try again','load')}</div>`}}
root.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const [action,arg]=el.dataset.action.split(':');if(action==='load')return load();if(!state)return;if(['deck','help','saves'].includes(action)){modal=action;render();return}if(action==='close'){modal=null;render();return}if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='well-be-in-touch-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(action==='import'){document.querySelector('#import-file').click();return}if(action==='retry'){await save();return}if(action==='start')start(state);if(action==='hub')state.run=null;if(action==='upgrade')upgrade(state);if(action==='encounter')encounter(state,arg);if(action==='play'&&!play(state,Number(arg)))return;if(action==='end')endTurn(state);if(action==='reward')reward(state,arg==='skip'?null:arg);save()});
root.addEventListener('change',async e=>{if(e.target.id!=='import-file'||!e.target.files[0])return;try{const file=e.target.files[0];if(file.size>100000)throw Error('Save file is too large.');const imported=JSON.parse(await file.text());if(!validSave(imported))throw Error('That file is not a supported game save.');if(!confirm('Replace your current progress with this save?'))return;state=imported;modal=null;save()}catch(err){error=err.message;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){modal=null;render();return}if(modal||!state?.run||state.run.phase!=='combat'||['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.repeat)return;if(e.key.toLowerCase()==='e'){endTurn(state);save()}else if(/^[0-9]$/.test(e.key)){if(play(state,e.key==='0'?9:Number(e.key)-1))save()}});
await load();
